﻿using Lecos.Strassennamen.Data.Interfaces.Export;
using Lecos.Strassennamen.RestAPI.Authorization;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace Lecos.Strassennamen.RestAPI.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(ClientRoles.AppAccess)]
public class ExportController(
    IXmlExportService exportService
    ) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<string?>> CreateXml(long strassenId)
    {
        var result = await exportService.CreateXmlStrassenData(new List<long>() { strassenId });

        exportService.WriteXmlToFile(@"Export\strassen.xml", result);

        return Ok(result);
    }
