namespace Lecos.Strassennamen.Data.Export.Services;

public class XmlExportService(
	AppDbContext db,
	IStrasseStatusRepository strasseStatusRepository
	) : IXmlExportService
{
	public void WriteXmlToFile(string pathFilename, string data)
	{
		if (pathFilename == null || data == null)
		{
			return;
		}

		var dir = Path.GetDirectoryName(pathFilename) ?? string.Empty;

		Directory.CreateDirectory(dir);
		File.WriteAllText(pathFilename, data, Encoding.UTF8);
	}

	public async Task<string> CreateXmlStrassenData(List<long>? strassenIds = null, StrasseStatus? filterStrassenStatus = null)
	{
		var strassen = await db.Strassen
			.Where(x => strassenIds == null || strassenIds.Contains(x.Id))
			.AsSplitQuery()
			.AsNoTracking()
			.ToListAsync();
		var strassenStatus = await strasseStatusRepository.GetStatusAndLatestVorgangForStrassen(strassen);
		var strassenFiltered = filterStrassenStatus == null 
			? strassen 
			: strassen
				.Where(x => strassenStatus.ContainsKey(x.Id) && strassenStatus[x.Id].status == filterStrassenStatus)
				.ToList();

		foreach (var strasse in strassenFiltered)
		{
			if (strassenStatus.TryGetValue(strasse.Id, out var statusData))
			{
				strasse.InkraftDatum = statusData.inKraftDatum;
			}
		}

		return await CreateXmlStrassenData(strassenFiltered);
	}

